   206			return nil, fmt.Errorf("oauth: decode MCP_OAUTH_ENCRYPTION_KEY (must be base64): %w", err)
   207		}
   208		enc, err := security.NewEncryptor(keyBytes)
   209		if err != nil {
   210			return nil, fmt.Errorf("oauth: create encryptor: %w", err)
   211		}
   212		return enc, nil
   213	}
   214	
   215	// newStore creates the token storage backend based on cfg.StorageType.
   216	func newStore(_ context.Context, cfg Config, _ *slog.Logger) (combinedStore, func(), error) {
   217		return newStoreWithEncryptor(context.Background(), cfg, slog.Default(), nil)
   218	}
   219	
   220	// newStoreWithEncryptor creates the token storage backend with optional token
   221	// encryption at rest.
   222	func newStoreWithEncryptor(_ context.Context, cfg Config, _ *slog.Logger, enc *security.Encryptor) (combinedStore, func(), error) {
   223		if cfg.StorageType == storageTypeValkey {
   224			return newValkeyStoreWithEncryptor(cfg, enc)
   225		}
   226		// Default: in-process memory store (dev / single-replica).
   227		s := memory.New(memory.WithEncryptor(enc))
   228		return s, s.Stop, nil
   229	}
   230	
   231	// newValkeyStore creates a production Valkey storage backend.
   232	func newValkeyStore(cfg Config) (combinedStore, func(), error) {
   233		return newValkeyStoreWithEncryptor(cfg, nil)
   234	}
   235	
   236	// newValkeyStoreWithEncryptor creates a production Valkey storage backend with
   237	// optional token encryption at rest.
   238	func newValkeyStoreWithEncryptor(cfg Config, enc *security.Encryptor) (combinedStore, func(), error) {
   239		if cfg.ValkeyURL == "" {
   240			return nil, nil, fmt.Errorf("oauth: VALKEY_URL must be set when OAUTH_STORAGE=valkey")
   241		}
   242	
   243		vcfg := valkey.Config{
   244			Address:  cfg.ValkeyURL,
   245			Password: cfg.ValkeyPassword,
   246		}
   247		if cfg.ValkeyKeyPrefix != "" {
   248			vcfg.KeyPrefix = cfg.ValkeyKeyPrefix
   249		}
   250		if cfg.ValkeyTLS {
   251			vcfg.TLS = &tls.Config{MinVersion: tls.VersionTLS12}
   252		}
   253	
   254		s, err := valkey.New(vcfg, valkey.WithEncryptor(enc))
   255		if err != nil {
   256			return nil, nil, fmt.Errorf("oauth: connect to Valkey at %s: %w", cfg.ValkeyURL, err)
   257		}
   258		return s, func() { s.Close() }, nil
   259	}
